  ('N4.1-10', 'lesson', null, false, 'national', 'N4', 'N4.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 2, 'recall', 'A higher LTV means less risk for the lender.', '["True","False"]'::jsonb, '1'::jsonb, 'False.', '["A higher LTV means the borrower has less equity cushion, which is more risk for the lender.",""]'::jsonb, 'More loan, more risk.', null, '[]'::jsonb, null, 'higher-ltv-lower-risk-false', 'unverified'),
  ('N4.1-11', 'lesson', null, false, 'national', 'N4', 'N4.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'number', 2, 'calculation', 'A buyer gets a 95% LTV loan on a $320,000 home that appraises at price. How much is the down payment?', '[]'::jsonb, '{"value":16000,"tolerance":0,"unit":"dollars"}'::jsonb, 'A 95% loan leaves 5% to pay in cash: $16,000.', '[]'::jsonb, 'Down payment plus loan equals price.', 'Down payment = price × (100% − LTV)', '["100% − 95% = 5% = 0.05.","$320,000 × 0.05 = $16,000."]'::jsonb, null, 'down-payment-from-ltv', 'unverified'),
  ('N4.1-12', 'lesson', null, false, 'national', 'N4', 'N4.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'application', 'Under the federal Homeowners Protection Act, PMI on most conventional loans automatically ends when the balance is scheduled to reach:', '["50% of the original value","It never ends","90% of current value","78% of the original value"]'::jsonb, '3'::jsonb, 'Borrowers can request cancellation at 80%, and it ends automatically at 78% of original value if they''re current.', '["It ends well before 50%.","Federal law requires it to end.","The test uses original value and a lower percentage.",""]'::jsonb, 'Ask at 80, automatic at 78.', null, '[]'::jsonb, null, 'pmi-cancellation-hpa', 'unverified'),
