  ('N4.2-02', 'lesson', null, false, 'national', 'N4', 'N4.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'Which loan is guaranteed by the government and often requires no down payment for eligible veterans?', '["Conventional loan","FHA loan","Jumbo loan","VA loan"]'::jsonb, '3'::jsonb, 'VA loans are partially guaranteed for eligible veterans and often have no down payment.', '["Conventional loans aren''t government-backed.","FHA insures loans and usually requires some down payment.","Jumbo loans are large conventional loans.",""]'::jsonb, 'FHA insures, VA guarantees.', null, '[]'::jsonb, null, 'va-guaranteed-no-down', 'unverified'),
  ('N4.2-03', 'lesson', null, false, 'national', 'N4', 'N4.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'An ARM''s interest rate is set by adding:', '["The cap to the index","A margin to an index","PMI to the rate","Points to the APR"]'::jsonb, '1'::jsonb, 'An ARM rate equals the index plus a fixed margin, subject to caps.', '["Caps limit changes; they don''t set the rate.","","PMI is insurance, not part of the rate.","Points and APR aren''t how ARM rates adjust."]'::jsonb, 'Index moves, margin stays.', null, '[]'::jsonb, null, 'arm-index-margin', 'unverified'),
  ('N4.2-04', 'lesson', null, false, 'national', 'N4', 'N4.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'number', 2, 'calculation', 'An ARM has a 2.75% margin. At adjustment, the index is 4.10%, and the cap allows the change. What is the new interest rate, in percent?', '[]'::jsonb, '{"value":6.85,"tolerance":0.001,"unit":"%"}'::jsonb, 'Index plus margin is 6.85%.', '[]'::jsonb, 'Index moves, margin stays.', 'ARM rate = index + margin', '["4.10% + 2.75% = 6.85%."]'::jsonb, null, 'arm-rate-calc', 'unverified'),
