  ('N4.3-02', 'lesson', null, false, 'national', 'N4', 'N4.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'In a deed of trust, the lender is the:', '["Trustee","Beneficiary","Mortgagor","Trustor"]'::jsonb, '1'::jsonb, 'Deed of trust parties: trustor (borrower), trustee, beneficiary (lender).', '["The trustee is the neutral third party who holds title.","","Mortgagor is the borrower under a mortgage.","The trustor is the borrower."]'::jsonb, 'The lender benefits: beneficiary.', null, '[]'::jsonb, null, 'deed-of-trust-parties', 'unverified'),
