  ('N6.2-11', 'lesson', null, false, 'national', 'N6', 'N6.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'LAW', 'mcq', 1, 'recall', 'Carbon monoxide in a home is most likely caused by:', '["Asbestos tiles","Lead pipes","Radon","A faulty fuel-burning appliance like a furnace or water heater"]'::jsonb, '3'::jsonb, 'CO comes from incomplete combustion.', '["Asbestos is a fiber hazard.","Lead pipes affect water.","Radon is a different gas from soil.",""]'::jsonb, 'Burn fuel badly, make CO.', null, '[]'::jsonb, null, 'co-source', 'unverified'),
  ('N6.2-12', 'lesson', null, false, 'national', 'N6', 'N6.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'LAW', 'scenario', 2, 'application', 'You''re leasing a 1972 duplex for an owner. What should the agent do about lead?', '["Tell the tenant to research it themselves","Make sure the owner gives the lead disclosure and EPA pamphlet before the tenant signs","Paint over old paint and skip the disclosure","Nothing, because the rule covers only sales"]'::jsonb, '1'::jsonb, 'The lead rule covers both sales and most leases of pre-1978 housing.', '["The disclosure is the owner''s legal duty, with agents ensuring compliance.","","Covering paint doesn''t remove the duty.","The rule covers most leases of pre-1978 housing too."]'::jsonb, 'Built before ''78? Disclose lead.', null, '[]'::jsonb, null, 'agent-pre1978-rental', 'unverified'),
